@push('scripts')<script>
const openModal=(id)=>document.getElementById(id)?.classList.add('open'); const closeModal=(el)=>el.closest('.pa-modal-backdrop')?.classList.remove('open');
document.addEventListener('click',e=>{const open=e.target.closest('[data-open-modal]');if(open)openModal(open.dataset.openModal);if(e.target.closest('[data-close-modal]'))closeModal(e.target);const bulk=e.target.closest('[data-bulk-status]');if(bulk){const ids=[...document.querySelectorAll('.company-check:checked')];if(!ids.length)return alert('حدد شركة واحدة على الأقل');document.getElementById('bulkStatus').value=bulk.dataset.bulkStatus;document.getElementById('bulkForm').submit();}if(e.target.id==='selectAll'){document.querySelectorAll('.company-check').forEach(x=>x.checked=true);document.getElementById('allCompanies').checked=true;}});document.getElementById('allCompanies')?.addEventListener('change',e=>document.querySelectorAll('.company-check').forEach(x=>x.checked=e.target.checked));document.querySelectorAll('.pa-modal-backdrop').forEach(x=>x.addEventListener('click',e=>{if(e.target===x)x.classList.remove('open')}));
</script>@endpush
@endsection
